import { tv, type VariantProps } from "@/lib/beton/tv";

export const label = tv({
  slots: {
    root: [
      "inline-flex items-center gap-1 font-display font-bold uppercase tracking-wide text-foreground",
      "data-disabled:cursor-not-allowed data-disabled:text-disabled-foreground",
    ],
    indicator: "font-mono text-foreground",
  },
  variants: {
    size: {
      sm: { root: "text-xs" },
      md: { root: "text-sm" },
      lg: { root: "text-base" },
    },
  },
  defaultVariants: {
    size: "md",
  },
});

export type LabelVariants = VariantProps<typeof label>;

import { label, type LabelVariants } from "@/lib/beton/recipes/label.recipe";
import type { ComponentProps } from "react";
import { dataAttr } from "@/lib/beton/render-element";

export interface LabelProps extends ComponentProps<"label">, LabelVariants {
  /** Shows a required marker. Also set `required` on the associated control. */
  required?: boolean;
  /** Styles the label as disabled. */
  disabled?: boolean;
}

export function Label({
  size = "md",
  required = false,
  disabled = false,
  className,
  children,
  ...props
}: LabelProps) {
  const styles = label({ size });
  return (
    <label
      {...props}
      data-size={size}
      data-disabled={dataAttr(disabled)}
      className={styles.root({ class: className })}
    >
      {children}
      {required ? (
        <span aria-hidden="true" className={styles.indicator()}>
          *
        </span>
      ) : null}
    </label>
  );
}
